  const tasks=[];
  const mk=(projectId,stageId,title,status,priority,start,due,assignee,description,position)=>{const t={id:id(),projectId,stageId,title,status,priority,startDate:start,dueDate:due,assignee,description,progress:status==='done'?100:status==='doing'?55:status==='approval'?80:status==='blocked'?30:10,checklist:[],position,inbox:false,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};tasks.push(t);return t};
  const a=mk(p1,s11,'Утвердить концепцию','approval','high',addDays(-1),addDays(0),'Алия','Фиксируем финальную версию перед запуском',{x:-7.2,y:3.0});
