  const c=mk(p1,s13,'Передать материалы подрядчику','planned','medium',addDays(3),addDays(4),'Мария','Финальная передача материалов',{x:-7.0,y:-1});
  const d=mk(p2,s21,'Собрать программу мероприятия','doing','high',addDays(-2),addDays(2),'Алексей','Проверить тайминг, участников и площадку',{x:4.0,y:3.0});
  const e=mk(p2,s21,'Подтвердить спикеров','approval','medium',addDays(-1),addDays(0),'Мария','Получить подтверждение участников',{x:7.2,y:1.2});
  const f=mk(p2,s22,'Печать программы','planned','medium',addDays(3),addDays(5),'Подрядчик','Запуск после финального тайминга',{x:4.2,y:-1});
  mk(p3,s31,'Подготовить аналитику за месяц','doing','medium',addDays(-2),addDays(5),'Алия','Собрать показатели и комментарии',{x:0,y:-5});
