function normalizeState(raw){
  const s=raw&&typeof raw==='object'?raw:starter();
  const knownDemo=!s.meta&&['Запуск кампании','Форум','Система отчётности'].every(name=>s.projects?.some(p=>p.name===name));
  s.version=5;s.meta=s.meta||{demo:knownDemo};s.organizations=s.organizations||[];s.projects=s.projects||[];s.tasks=s.tasks||[];s.relations=s.relations||[];s.stages=s.stages||[];s.milestones=s.milestones||[];s.events=s.events||[];
  if(!s.organizations.length)s.organizations.push({id:id(),name:'Рабочие проекты',color:COLORS[0]});
  for(const [i,p] of s.projects.entries()){
    p.description??='';p.owner??='';p.members??=[];p.startDate??='';p.dueDate??='';p.color??=COLORS[i%COLORS.length];p.status??='active';p.archived??=false;
    let stages=s.stages.filter(x=>x.projectId===p.id);
    if(!stages.length){stages=[{id:id(),projectId:p.id,name:'Подготовка',order:1},{id:id(),projectId:p.id,name:'Реализация',order:2},{id:id(),projectId:p.id,name:'Завершение',order:3}];s.stages.push(...stages)}
    for(const t of s.tasks.filter(x=>x.projectId===p.id)){t.stageId??=stages[0]?.id||''}
  }
  for(const t of s.tasks){t.startDate??='';t.dueDate??='';t.description??='';t.assignee??='';t.status??='planned';t.priority??='medium';t.progress??=0;t.checklist??=[];t.position??=null;t.inbox=!!t.inbox||!t.projectId}
  return s;
}

