const projectBy=x=>state.projects.find(p=>p.id===x), taskBy=x=>state.tasks.find(t=>t.id===x), stageBy=x=>state.stages.find(s=>s.id===x);
const statusName=v=>STATUS.find(x=>x[0]===v)?.[1]||v, priorityName=v=>PRIORITY.find(x=>x[0]===v)?.[1]||v;
const projectStages=p=>state.stages.filter(s=>s.projectId===p).sort((a,b)=>a.order-b.order);
const projectTasks=p=>state.tasks.filter(t=>t.projectId===p);
const projectMilestones=p=>state.milestones.filter(m=>m.projectId===p).sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999'));
function isOverdue(t){return !!t.dueDate&&effectiveStatus(t)!=='done'&&dateObj(t.dueDate)<new Date(new Date().setHours(0,0,0,0))}
function predecessors(t){const ids=[];for(const r of state.relations){if(r.type==='blocks'&&r.targetId===t.id)ids.push(r.sourceId);if(r.type==='depends'&&r.sourceId===t.id)ids.push(r.targetId)}return ids.map(taskBy).filter(Boolean)}
function autoBlockers(t){if(t.status==='done')return[];return predecessors(t).filter(p=>effectiveStatusBase(p)!=='done')}
function effectiveStatusBase(t){return t?.status||'planned'}
function effectiveStatus(t){if(!t)return'planned';if(t.status==='done')return'done';if(t.status==='blocked')return'blocked';return autoBlockers(t).length?'blocked':t.status}
function isRisk(t){const st=effectiveStatus(t);return st==='blocked'||isOverdue(t)||(t.priority==='high'&&st!=='done'&&t.dueDate&&dateObj(t.dueDate)-Date.now()<3*864e5)}
let scheduleCache=new Map();
function projectSchedule(projectId){if(!scheduleCache.has(projectId)){const tasks=projectTasks(projectId);scheduleCache.set(projectId,{slack:slackByTask(tasks,state.relations),chain:criticalChain(tasks,state.relations),progress:computeProgress(tasks)})}return scheduleCache.get(projectId)}
const projectProgress=p=>projectSchedule(p).progress.percent;
function slackChip(t){if(!t.projectId)return '';const s=projectSchedule(t.projectId).slack.get(t.id);if(s===undefined)return '';if(s===0)return '<span class="slack slack-none">без запаса</span>';return `<span class="slack">запас ${s} ${word(s,'день','дня','дней')}</span>`}
function projectRiskCount(p){return projectTasks(p).filter(isRisk).length}
function word(n,one,few,many){const a=Math.abs(n)%100,b=a%10;return a>10&&a<20?many:b===1?one:b>1&&b<5?few:many}
function setSaveState(text='Сохранено'){const el=document.querySelector('#saveState');if(el)el.textContent=text}
function scheduleSave(){scheduleCache.clear();dirty=true;const generation=++editGeneration;clearTimeout(saveTimer);setSaveState('Сохраняю…');saveTimer=setTimeout(async()=>{try{await persist();if(generation===editGeneration)dirty=false;setSaveState(hosted?'Общая база · сохранено':'На устройстве · сохранено')}catch(e){setSaveState('Не сохранено');toast(e.message);showSaveRecovery(e)}},180)}
function showSaveRecovery(e){if(document.querySelector('#saveRecovery'))return;const box=document.createElement('div');box.id='saveRecovery';box.className='save-recovery';box.innerHTML='<strong>Изменения не сохранены</strong><p></p><button class="btn" data-backup>Скачать мои изменения</button><button class="btn primary" data-reload>Обновить общую базу</button>';box.querySelector('p').textContent=e.message;box.querySelector('[data-backup]').onclick=exportWorkspace;box.querySelector('[data-reload]').onclick=()=>{if(confirm('Несохранённые изменения будут потеряны. Вы скачали копию?')){dirty=false;location.reload()}};document.body.append(box)}

function toast(msg,action){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.innerHTML=`<span>${esc(msg)}</span>${action?'<button>Отменить</button>':''}`;document.body.appendChild(el);if(action)el.querySelector('button').onclick=()=>{action();el.remove()};setTimeout(()=>el.remove(),action?5000:2200)}
let restoringRoute=false,routeReady=false;
function updateUrl(replace=false){
  if(restoringRoute)return;
  const q=new URLSearchParams;
  if(view!=='home')q.set('view',view);
  if(currentProject!=='all')q.set('project',currentProject);
  if(scope!=='all')q.set('scope',scope);
  if(search)q.set('q',search);
  if(selectedTaskId)q.set('task',selectedTaskId);else if(selectedProjectId)q.set('focus',selectedProjectId);
  if(view==='docs')documentsUI.writeRoute(q);
  const url=location.pathname+location.search+(q.size?'#'+q:'');
  if(!routeReady){history.replaceState({hq:true,scroll:0},'',url);routeReady=true;}
  else if(url!==location.pathname+location.search+location.hash)history[replace?'replaceState':'pushState']({hq:true,scroll:0},'',url);
}
function restoreRoute(){
  restoringRoute=true;
  const q=new URLSearchParams(location.hash.slice(1));
  view=['home','mine','list','kanban','calendar','board','hq','people','problems','docs','integrations','notifications','archive'].includes(q.get('view'))?q.get('view'):'home';
  if(view==='docs'&&!isAdmin())view='home';
  currentProject=q.get('project')==='inbox'||state.projects.some(p=>p.id===q.get('project'))?q.get('project'):'all';
  scope=SCOPES.some(([k])=>k===q.get('scope'))?q.get('scope'):'all';search=q.get('q')||'';
  selectedTaskId=state.tasks.some(t=>t.id===q.get('task'))?q.get('task'):null;
  selectedProjectId=!selectedTaskId&&state.projects.some(p=>p.id===q.get('focus'))?q.get('focus'):null;
  if(isWorkView(view)&&view!=='board')lastWorkView=view;
  documentsUI.restoreRoute(q);renderAll(true);restoringRoute=false;
  requestAnimationFrame(()=>{const area=document.querySelector('#main .main-scroll');if(area)area.scrollTop=history.state?.scroll||0;});
}
addEventListener('popstate',restoreRoute);
document.addEventListener('scroll',e=>{if(!restoringRoute&&e.target.matches?.('#main .main-scroll'))history.replaceState({...history.state,scroll:e.target.scrollTop},'');},true);
async function setView(next){if(isWorkView(next)&&next!=='board')lastWorkView=next;if(next==='board'&&dirty){clearTimeout(saveTimer);try{await persist();dirty=false;}catch(e){showSaveRecovery(e);return;}}if(next==='docs'&&!isAdmin())return;if(view==='docs'&&next!=='docs'){try{await documentsUI.flush();}catch(e){toast(e.message);return;}}view=next;if(next==='home')workflow.resetHome();if(!isWorkView(next)){selectedTaskId=null;selectedProjectId=null;}document.querySelectorAll('.view-tabs [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelector('[data-place=work]')?.classList.toggle('active',isWorkView(view));renderMain();renderInspector();updateUrl()}

const criticalPath=p=>projectSchedule(p).chain;
function allCriticalIds(){const set=new Set();for(const p of state.projects)projectSchedule(p.id).chain.forEach(x=>set.add(x));return set}

function filteredTasks(){
  let items=[...state.tasks];
  if(currentProject==='inbox')items=items.filter(t=>!t.projectId||t.inbox);
  else{if(currentProject!=='all')items=items.filter(t=>t.projectId===currentProject)}
  if(scope==='today')items=items.filter(t=>t.dueDate===todayISO()&&effectiveStatus(t)!=='done');
  if(scope==='overdue')items=items.filter(isOverdue);
  if(scope==='blocked')items=items.filter(t=>effectiveStatus(t)==='blocked');
  if(scope==='week'){const end=addDays(7);items=items.filter(t=>(t.dueDate&&t.dueDate>=todayISO()&&t.dueDate<=end)||isOverdue(t))}
  if(scope==='risks')items=items.filter(isRisk);
  if(scope==='approval')items=items.filter(t=>effectiveStatus(t)==='approval');
  if(scope==='critical'){const ids=allCriticalIds();items=items.filter(t=>ids.has(t.id))}
  if(search){const q=search.toLowerCase();items=items.filter(t=>`${t.title} ${t.description} ${t.assignee} ${projectBy(t.projectId)?.name||''} ${stageBy(t.stageId)?.name||''}`.toLowerCase().includes(q))}
  return items;
}
function updateTask(taskId,patch){
  const t=taskBy(taskId);if(!t)return;
  if(!canEditTask(t)||(!isAdmin()&&Object.keys(patch).some(k=>!['status','progress','checklist'].includes(k)))){toast('Можно отмечать только свои задачи');return;}
  if(hosted&&['done','approval'].includes(patch.status)&&t.status!=='done'){
    if(t.status==='approval'){if(isAdmin())workflow.review(t,'accept');return;}
    if(patch.status==='approval'||t.requiresReview===true||t.result?.review?.decision==='return'){workflow.submit(t);return;}
  }
  const next={...t,...patch};if(next.startDate&&next.dueDate&&next.dueDate<next.startDate){toast('Срок не может быть раньше даты начала');renderInspector();return;}
  if(patch.status==='done'&&t.status!=='done'){const previous={status:t.status,progress:t.progress};toast('Готово — задача закрыта',()=>updateTask(taskId,previous));}
  if(patch.status==='done')patch={...patch,progress:100};
  Object.assign(t,patch,{updatedAt:new Date().toISOString()});if(patch.projectId!==undefined)t.inbox=!patch.projectId;
  const scroll=document.querySelector('#main .main-scroll')?.scrollTop||0;
  scheduleSave();renderMain();renderSidebar();renderInspector();const area=document.querySelector('#main .main-scroll');if(area)area.scrollTop=scroll;
}
function addTask(data,{quick=false}={}){const p=projectBy(data.projectId);const t={id:id(),title:data.title||'Новая задача',description:data.description||'',projectId:p?.id||'',stageId:data.stageId||projectStages(p?.id)[0]?.id||'',status:data.status||'planned',priority:data.priority||'medium',startDate:data.startDate||'',dueDate:data.dueDate||'',assignee:data.assignee||'',lead:data.assignee||'',contributors:[],expectedResult:data.expectedResult||'',requiresReview:data.requiresReview===true,progress:0,checklist:data.checklist||[],position:null,inbox:!p,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};if(hosted){t.createdBy=session.me.email;t.assigneeEmail=isAdmin()?(session.team.find(m=>m.name===t.assignee)?.email||''):session.me.email;if(!isAdmin()){t.assignee=session.me.name;t.assignees=[session.me.name];t.assigneeEmails=[session.me.email];t.requiresReview=false;t.lead=session.me.name;t.contributors=[];}}state.tasks.unshift(t);selectedTaskId=quick?null:t.id;selectedProjectId=null;scheduleSave();renderAll(true);toast('Задача создана')}
function deleteTask(taskId){if(!isAdmin()){toast('Действие доступно администратору');return;}const task=taskBy(taskId),rels=state.relations.filter(r=>r.sourceId===taskId||r.targetId===taskId);if(!task||!confirm(`Удалить задачу «${task.title}»?`))return;state.tasks=state.tasks.filter(t=>t.id!==taskId);state.relations=state.relations.filter(r=>r.sourceId!==taskId&&r.targetId!==taskId);if(selectedTaskId===taskId)selectedTaskId=null;scheduleSave();renderAll(false);toast('Задача удалена',()=>{state.tasks.unshift(task);state.relations.push(...rels);scheduleSave();renderAll(false)})}
function deleteProject(projectId){if(!isAdmin()){toast('Действие доступно администратору');return;}const project=projectBy(projectId);if(!project||!confirm(`Удалить проект «${project.name}» вместе с его задачами?`))return;const pack={project,tasks:projectTasks(projectId),stages:projectStages(projectId),milestones:projectMilestones(projectId)},taskIds=new Set(pack.tasks.map(t=>t.id));pack.relations=state.relations.filter(r=>taskIds.has(r.sourceId)||taskIds.has(r.targetId));state.projects=state.projects.filter(p=>p.id!==projectId);state.tasks=state.tasks.filter(t=>t.projectId!==projectId);state.stages=state.stages.filter(s=>s.projectId!==projectId);state.milestones=state.milestones.filter(m=>m.projectId!==projectId);state.relations=state.relations.filter(r=>!taskIds.has(r.sourceId)&&!taskIds.has(r.targetId));currentProject='all';selectedProjectId=null;selectedTaskId=null;scheduleSave();renderAll(false);toast('Проект удалён',()=>{state.projects.push(pack.project);state.tasks.push(...pack.tasks);state.stages.push(...pack.stages);state.milestones.push(...pack.milestones);state.relations.push(...pack.relations);scheduleSave();renderAll(false)})}
function duplicateProject(projectId){if(!isAdmin()){toast('Действие доступно администратору');return;}const source=projectBy(projectId);if(!source)return;const pid=id(),now=new Date().toISOString(),stageMap=new Map(),taskMap=new Map();const copy={...source,id:pid,name:`${source.name} — копия`,archived:false,createdAt:now,updatedAt:now,members:[...(source.members||[])]};state.projects.push(copy);for(const stage of projectStages(projectId)){const next={...stage,id:id(),projectId:pid};stageMap.set(stage.id,next.id);state.stages.push(next)}for(const task of projectTasks(projectId)){const next={...task,id:id(),projectId:pid,stageId:stageMap.get(task.stageId)||'',checklist:(task.checklist||[]).map(x=>({...x})),position:null,createdAt:now,updatedAt:now};taskMap.set(task.id,next.id);state.tasks.push(next)}for(const milestone of projectMilestones(projectId))state.milestones.push({...milestone,id:id(),projectId:pid,stageId:stageMap.get(milestone.stageId)||''});for(const relation of state.relations.filter(r=>taskMap.has(r.sourceId)&&taskMap.has(r.targetId)))state.relations.push({...relation,id:id(),sourceId:taskMap.get(relation.sourceId),targetId:taskMap.get(relation.targetId)});currentProject=pid;scope='all';selectedProjectId=pid;selectedTaskId=null;scheduleSave();renderAll(false);toast('Проект скопирован')}
function addRelation(a,b,type='blocks'){if(!isAdmin()){toast('Действие доступно администратору');return;}if(a===b||state.relations.some(r=>r.sourceId===a&&r.targetId===b&&r.type===type))return;const cycle=wouldCreateCycle(state.tasks,state.relations,a,b,type);if(cycle){toast(`Связь создаст цикл: ${cycle.map(x=>taskBy(x)?.title||'?').join(' → ')}`);return}state.relations.push({id:id(),sourceId:a,targetId:b,type});scheduleSave();renderInspector();renderMain();toast('Связь создана')}

const WORK_VIEWS=[['list','Список'],['kanban','Доска'],['calendar','Календарь'],['board','Свободный холст'],['hq','Связи']];
