function renderSidebar(){
  const el=document.querySelector('#sidebar');if(!el)return;
  const inbox=state.tasks.filter(t=>!t.projectId||t.inbox).length;
  const activeProjects=state.projects.filter(p=>!p.archived);
  let html=`<div class="side-title"><b>Пространство</b><button class="icon-btn" id="newOrg" aria-label="Управление пространствами" title="Управление пространствами">⚙</button></div><div class="tree"><div class="project-link ${currentProject==='inbox'?'active':''}" data-project="inbox" role="button" tabindex="0"><span>📥 Входящие</span><span class="count-pill">${inbox}</span></div><div class="project-link all-projects ${currentProject==='all'?'active':''}" data-project="all" role="button" tabindex="0"><span>Все проекты</span><span class="count-pill">${activeProjects.length}</span></div>`;
  for(const org of state.organizations){const ps=activeProjects.filter(p=>p.orgId===org.id);html+=`<div class="org"><div class="org-head"><span class="dot" style="background:${org.color||COLORS[0]}"></span>${esc(org.name)}</div>${ps.map(p=>`<div class="project-link ${currentProject===p.id?'active':''}" data-project="${p.id}" role="button" tabindex="0"><span>${esc(p.name)}</span><span class="count-pill">${projectRiskCount(p.id)?`⚠ ${projectRiskCount(p.id)}`:projectTasks(p.id).length}</span></div>`).join('')}</div>`}
  html+=`</div><div class="side-sep"></div><div class="filter-set side-links"><button class="filter-btn ${view==='integrations'?'active':''}" data-side-view="integrations">Подключения</button></div>`;
  el.innerHTML=html;
  el.querySelectorAll('[data-project]').forEach(x=>{const go=async()=>{if(view==='docs'){try{await documentsUI.flush();}catch(e){toast(e.message);return;}}currentProject=x.dataset.project;scope='all';view=lastWorkView;documentsUI.reset();selectedTaskId=null;selectedProjectId=null;renderAll(false);updateUrl()};x.onclick=go;x.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}}});
  el.querySelectorAll('[data-side-view]').forEach(x=>x.onclick=()=>setView(x.dataset.sideView));el.querySelector('#newOrg').onclick=openOrgModal;if(!isAdmin())el.querySelector('#newOrg').hidden=true;
}
function summary(items){return{overdue:items.filter(isOverdue).length,today:items.filter(t=>t.dueDate===todayISO()&&effectiveStatus(t)!=='done').length,blocked:items.filter(t=>effectiveStatus(t)==='blocked').length,approval:items.filter(t=>effectiveStatus(t)==='approval').length}}
// The same four numbers, the same words and the same filters on every screen.
function kpiStrip(items){const s=summary(items);return`<div class="kpi-strip">${[['overdue','Просрочено','срок прошёл',s.overdue],['today','Сегодня','срок сегодня',s.today],['blocked','Заблокировано','ждут другие задачи',s.blocked],['approval','Ждут решения','на согласовании',s.approval]].map(([k,n,d,v])=>`<button class="kpi kpi-${k} ${v?'has':''}" data-kpi="${k}"><span>${n}</span><strong>${v}</strong><small>${d}</small></button>`).join('')}</div>`}
function bindKpis(main){main.querySelectorAll('[data-kpi]').forEach(x=>x.onclick=()=>{scope=x.dataset.kpi;setView(isWorkView(view)&&view!=='board'?view:lastWorkView)})}
function pageTitle(){if(currentProject==='inbox')return'Входящие';if(currentProject!=='all')return projectBy(currentProject)?.name||'Проект';if(scope==='today')return'Срок сегодня';if(scope==='overdue')return'Просрочено';if(scope==='blocked')return'Заблокировано';if(scope==='week')return'Неделя';if(scope==='risks')return'Риски';if(scope==='approval')return'Ждут решения';if(scope==='critical')return'Критический путь';return'Все проекты'}
function contextName(){if(currentProject==='inbox')return'Входящие';if(currentProject!=='all')return projectBy(currentProject)?.name||'Проект';return'Все проекты'}
function contextBar(main){if(view==='board')return;if(hosted&&['home','mine'].includes(view)){if(!isAdmin()||view==='mine'||!search)return;const bar=document.createElement('div');bar.className='context-bar';bar.innerHTML='<span>Поиск по всем проектам:</span><b></b><button class="btn mini">Сбросить поиск</button>';bar.querySelector('b').textContent=search;bar.querySelector('button').onclick=()=>{search='';document.querySelector('#search').value='';renderMain();updateUrl()};main.prepend(bar);return;}const names={today:'Срок сегодня',overdue:'Просрочено',blocked:'Заблокировано',week:'Ближайшие 7 дней',risks:'Риски',approval:'Ждут решения',critical:'Критический путь'};const active=currentProject!=='all'||(scope!=='all'&&!isWorkView(view))||!!search;if(!active)return;const bar=document.createElement('div');bar.className='context-bar';bar.innerHTML=`<span>Показано:</span><b>${esc(contextName())}</b>${scope!=='all'?`<b>${esc(names[scope]||scope)}</b>`:''}${search?`<b>Поиск: ${esc(search)}</b>`:''}<button class="btn mini" data-reset-context>Сбросить</button>`;main.prepend(bar);bar.querySelector('[data-reset-context]').onclick=()=>{currentProject='all';scope='all';search='';selectedTaskId=null;selectedProjectId=null;document.querySelector('#search').value='';renderAll(false);updateUrl()}}
let lastRenderedView=null;
function renderMain(){const renderKey=[view,isWorkView(view)?currentProject:'',isWorkView(view)?scope:'',search].join('|');const saved=lastRenderedView===renderKey?captureSurface(document.querySelector('#main')):null;renderMainContent();restoreSurface(document.querySelector('#main'),saved);lastRenderedView=renderKey;}
function renderMainContent(){documentsUI.cancelRender();const main=document.querySelector('#main');if(!main)return;main.classList.remove('has-workbar');if(hq){hqSaved={key:hqKey(),view:hq.view};hq.destroy();hq=null}if(view==='board'){main.innerHTML='<div class="loading-state">Открываю доску…</div>';window.dispatchEvent(new CustomEvent('living-hq:open-board'));return}const items=filteredTasks();if(view==='home'&&hosted)workflow.home(main);else if(view==='mine'&&hosted)workflow.mine(main);else if(view==='notifications'&&hosted)workflow.notifications(main);else if(view==='archive'&&hosted)workflow.archive(main);else if(view==='home')renderHome(main,items);else if(view==='list')renderList(main,items);else if(view==='kanban')renderKanban(main,items);else if(view==='calendar')renderCalendar(main,items);else if(view==='people')renderPeople(main,items);else if(view==='problems')teamUI.problems(main);else if(view==='docs'&&isAdmin())documentsUI.render(main).then(()=>{if(view==='docs'&&history.state?.scroll)main.querySelector('.main-scroll')?.scrollTo(0,history.state.scroll);});else if(view==='integrations')teamUI.integrations(main);else renderHQ(main,items);workBar(main);contextBar(main)}
function taskStatusChip(t){const st=effectiveStatus(t),auto=st==='blocked'&&t.status!=='blocked';return`<span class="status-chip status-${st}">${statusName(st)}${auto?' · авто':''}</span>`}
function nextAction(p){const tasks=projectTasks(p.id).filter(t=>effectiveStatus(t)!=='done').sort((a,b)=>{const ar=isRisk(a)?0:1,br=isRisk(b)?0:1;return ar-br||(a.dueDate||'9999').localeCompare(b.dueDate||'9999')});return tasks[0]}
// Each open task that needs someone becomes one sentence with the button that resolves it.
function actionFeed(items){
  const acts=[],who=t=>t.assignee||'без ответственного';
  for(const t of items){
    const st=effectiveStatus(t);if(st==='done')continue;const bl=autoBlockers(t);
    if(isOverdue(t)){const d=dayDiff(t.dueDate,todayISO());acts.push({w:0,t,kind:'late',text:`просрочена на ${d} ${word(d,'день','дня','дней')}`,btns:[['done','Готово'],['open','Открыть']]})}
    else if(st==='blocked'&&bl.length)acts.push({w:1,t,kind:'blocked',text:`ждёт «${bl[0].title}»${bl[0].assignee?` — ${bl[0].assignee}`:''}${bl.length>1?` и ещё ${bl.length-1}`:''}`,btns:[['chain','Показать цепочку'],['open:'+bl[0].id,'Открыть блокер']]});
    else if(st==='blocked')acts.push({w:1,t,kind:'blocked',text:'заблокирована вручную — узнайте, что мешает',btns:[['open','Открыть']]});
    else if(st==='approval')acts.push({w:2,t,kind:'approval',text:'ждёт решения',btns:[['approve','Согласовано'],['open','Открыть']]});
    else if(t.dueDate===todayISO())acts.push({w:3,t,kind:'today',text:'срок сегодня',btns:[['done','Готово'],['open','Открыть']]});
    else if(isRisk(t))acts.push({w:4,t,kind:'soon',text:`срочная, срок ${fmtDate(t.dueDate)}`,btns:[['open','Открыть']]});
    else if(!t.assignee)acts.push({w:5,t,kind:'owner',text:'нет ответственного',btns:[['open','Назначить']]});
  }
  return acts.sort((a,b)=>a.w-b.w||(a.t.dueDate||'9999').localeCompare(b.t.dueDate||'9999'));
}
let feedExpanded=false;
function renderHome(main,items){
  const open=items.filter(t=>effectiveStatus(t)!=='done'),acts=actionFeed(items),shown=feedExpanded?acts:acts.slice(0,7);
  const q=search.toLowerCase();const projects=state.projects.filter(p=>!p.archived&&(currentProject==='all'||p.id===currentProject)&&(!q||`${p.name} ${p.description} ${p.owner} ${(p.members||[]).join(' ')} ${projectTasks(p.id).map(t=>`${t.title} ${t.description} ${t.assignee}`).join(' ')}`.toLowerCase().includes(q))).map(p=>({p,risk:projectRiskCount(p.id),next:nextAction(p)})).sort((a,b)=>b.risk-a.risk||(a.p.dueDate||'9999').localeCompare(b.p.dueDate||'9999'));
  const kinds={late:'Просрочено',blocked:'Стоит',approval:'Решение',today:'Сегодня',soon:'Срочно',owner:'Назначить'};
  const dateLine=new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'});
  main.innerHTML=`<div class="main-scroll home-page">${state.meta?.demo?`<div class="demo-banner"><div><b>Это демонстрационное пространство</b><span>Можно изучить пример или начать со своих проектов.</span></div><button class="btn" data-keep-demo>Оставить пример</button><button class="btn primary" data-clean-start>Начать с чистого листа</button></div>`:''}<div class="page-head"><div><div class="eyebrow">${esc(dateLine)}${currentProject!=='all'?' · '+esc(contextName()):''}</div><h1>${acts.length?`${acts.length} ${word(acts.length,'дело требует','дела требуют','дел требуют')} внимания`:'Всё под контролем'}</h1><p>${acts.length?'Начните сверху: самое срочное — первым. Каждое дело закрывается одной кнопкой.':`Открыто ${open.length} ${word(open.length,'задача','задачи','задач')}, срочного нет.`}</p></div><button class="btn primary" id="homeQuick">+ Быстрая задача</button></div>${kpiStrip(items)}<section class="home-panel action-feed"><div class="home-panel-head"><div><span class="eyebrow">Что сделать сейчас</span><h2>Дела на сегодня</h2></div></div>${shown.map(a=>`<article class="act act-${a.kind}"><span class="act-kind">${kinds[a.kind]}</span><div class="act-body"><button class="act-title" data-task="${a.t.id}">${esc(a.t.title)}</button><span class="act-text">${esc(a.text)}</span><small>${esc(projectBy(a.t.projectId)?.name||'Входящие')} · ${esc(a.t.assignee||'без ответственного')}${a.t.dueDate?' · до '+fmtDate(a.t.dueDate):''}</small></div><div class="act-btns">${a.btns.map(([k,n],i)=>`<button class="btn ${i?'':'primary'}" data-act="${k}" data-id="${a.t.id}">${n}</button>`).join('')}</div></article>`).join('')||'<div class="home-empty act-empty"><b>Срочных дел нет</b><span>Можно спокойно заняться задачами из плана на неделю.</span></div>'}${acts.length>shown.length?`<button class="btn ghost act-more" data-more>Показать все (${acts.length})</button>`:''}</section><section class="home-panel project-pulse home-grid"><div class="home-panel-head"><div><span class="eyebrow">${currentProject==='all'?'Портфель':'Проект'}</span><h2>${currentProject==='all'?'Состояние проектов':'Состояние проекта'}</h2></div></div><div class="project-pulse-grid">${projects.map(({p,risk,next})=>`<button class="project-pulse-card" data-project-open="${p.id}"><div class="pulse-top"><span class="dot" style="background:${p.color}"></span><b>${esc(p.name)}</b><em class="${risk?'risk':''}">${risk?`⚠ ${risk}`:'Стабильно'}</em></div><div class="pulse-progress"><i style="width:${projectProgress(p.id)}%"></i></div><div class="pulse-meta"><span>${projectProgress(p.id)}% готово</span><span>${fmtDate(p.dueDate)}</span></div><div class="pulse-next"><small>Следующее действие</small><strong>${esc(next?.title||'Определить следующий шаг')}</strong></div></button>`).join('')||'<div class="home-empty">Ничего не найдено</div>'}</div></section></div>`;
  main.querySelector('#homeQuick').onclick=openQuickModal;bindKpis(main);
  main.querySelectorAll('[data-task]').forEach(x=>x.onclick=()=>{selectedTaskId=x.dataset.task;selectedProjectId=null;renderInspector()});
  main.querySelectorAll('[data-project-open]').forEach(x=>x.onclick=()=>{selectedProjectId=x.dataset.projectOpen;selectedTaskId=null;renderInspector()});
  main.querySelector('[data-more]')?.addEventListener('click',()=>{feedExpanded=true;renderMain()});
  main.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>runAction(b.dataset.act,b.dataset.id));
  main.querySelector('[data-keep-demo]')?.addEventListener('click',()=>{state.meta.demo=false;scheduleSave();renderMain()});main.querySelector('[data-clean-start]')?.addEventListener('click',startClean);teamUI.overview(main,items)
}
function runAction(kind,id){
  const t=taskBy(id);if(!t)return;
  if(kind==='open'||kind.startsWith('open:')){selectedTaskId=kind.startsWith('open:')?kind.slice(5):id;selectedProjectId=null;renderInspector();return}
  if(kind==='chain'){showChain(id);return}
  const before={status:t.status,progress:t.progress||0};
  updateTask(id,{status:'done',progress:100});
  if(taskBy(id)?.status==='done')toast(kind==='approve'?'Согласовано — задача закрыта':'Задача выполнена',()=>updateTask(id,before));
}
// Jump to «Связи» with the task's chain lit up.
function showChain(id){const t=taskBy(id);if(!t)return;scope='all';if(currentProject!=='all'&&t.projectId!==currentProject)currentProject='all';selectedTaskId=id;selectedProjectId=null;hqFocusId=id;renderSidebar();setView('hq')}
const taskAssignees=t=>[...new Set(String(t.assignee||'').split(/[;,]/).map(x=>canonicalName(x.trim())).filter(Boolean))];
