  main.innerHTML=`<div class="main-scroll people-page"><div class="page-head"><div><div class="eyebrow">Команда</div><h1>Люди и загрузка</h1><p>У кого много задач, где появились риски и что ждёт решения.</p></div></div><div class="people-grid">${names.map(name=>{const ts=items.filter(t=>name==='Без ответственного'?!taskAssignees(t).length:taskAssignees(t).includes(name)),open=ts.filter(t=>effectiveStatus(t)!=='done'),risk=open.filter(isRisk),approval=open.filter(t=>effectiveStatus(t)==='approval'),load=Math.min(100,open.reduce((n,t)=>n+(t.priority==='high'?25:t.priority==='medium'?16:10),0));return`<article class="person-card"><div class="person-head"><div class="person-avatar">${esc(name.slice(0,1).toUpperCase())}</div><div><h2>${esc(name)}</h2><p>${open.length} ${word(open.length,'активная','активные','активных')} · ${risk.length} ${word(risk.length,'риск','риска','рисков')}</p></div></div><div class="person-load ${load>72?'lvl-high':load>45?'lvl-mid':'lvl-low'}"><span>Загрузка</span><b>${load}%</b><i><em style="width:${load}%"></em></i></div><div class="person-stats"><span><b>${ts.filter(t=>t.dueDate===todayISO()).length}</b> сегодня</span><span><b>${approval.length}</b> решений</span><span><b>${risk.length}</b> рисков</span></div><div class="person-tasks">${open.sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999')).slice(0,3).map(t=>`<button data-task="${t.id}"><span>${esc(t.title)}</span><small class="${isOverdue(t)?'overdue':''}">${fmtDate(t.dueDate)}</small></button>`).join('')||'<small>Все задачи завершены</small>'}</div></article>`}).join('')||'<div class="empty-state"><h3>Пока нет исполнителей</h3><p>Назначьте ответственных в карточках задач.</p></div>'}</div></div>`;
  main.querySelectorAll('[data-task]').forEach(x=>x.onclick=()=>{selectedTaskId=x.dataset.task;selectedProjectId=null;renderInspector()});teamUI.people(main)
