function renderCalendar(main,items){
  main.innerHTML=`<div class="main-scroll calendar-page"><div class="page-head"><div><h1>Календарь и Timeline</h1><p>Сроки задач, вехи проектов и события команды</p></div>${isAdmin()?'<button class="btn primary" data-new-event>+ Событие</button>':''}<div class="segmented"><button class="btn ${calendarMode==='month'?'active':''}" data-calmode="month">Месяц</button><button class="btn ${calendarMode==='timeline'?'active':''}" data-calmode="timeline">Timeline</button></div></div><div id="calendarBody"></div></div>`;
  main.querySelectorAll('[data-calmode]').forEach(b=>b.onclick=()=>{calendarMode=b.dataset.calmode;renderCalendar(main,items)});main.querySelector('[data-new-event]')?.addEventListener('click',()=>openEventModal(null,todayISO()));calendarMode==='month'?renderMonth(main.querySelector('#calendarBody'),items):renderTimeline(main.querySelector('#calendarBody'),items)
}
function renderMonth(el,items){
  const a=new Date(monthAnchor);a.setDate(1);a.setHours(12,0,0,0);const start=new Date(a);const dow=(start.getDay()+6)%7;start.setDate(start.getDate()-dow);const monthName=a.toLocaleDateString('ru-RU',{month:'long',year:'numeric'});const visibleProjects=new Set(items.map(t=>t.projectId));const milestones=state.milestones.filter(m=>(currentProject==='all'||m.projectId===currentProject)&&(!visibleProjects.size||visibleProjects.has(m.projectId)));
  let html=`<div class="calendar-nav"><button class="btn" data-calnav="-1">←</button><strong>${monthName}</strong><button class="btn" data-calnav="1">→</button><button class="btn ghost" data-calnav="0">Сегодня</button></div><div class="month-grid">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(d=>`<div class="dow">${d}</div>`).join('')}`;
  for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const ds=iso(d),inMonth=d.getMonth()===a.getMonth(),dayTasks=items.filter(t=>t.dueDate===ds),dayMs=milestones.filter(m=>m.dueDate===ds),dayEv=(state.events||[]).filter(e=>e.date<=ds&&(e.endDate||e.date)>=ds).sort((x,y)=>(x.time||'').localeCompare(y.time||''));html+=`<div class="day-cell ${inMonth?'':'outside'} ${ds===todayISO()?'today-cell':''}" data-day="${ds}"><div class="day-num">${d.getDate()}</div>${dayEv.map(e=>`<button class="event-chip" data-event="${e.id}" title="${esc([e.time,e.title,e.place].filter(Boolean).join(' · '))}">${e.time?`<b>${esc(e.time)}</b> `:''}${esc(e.title)}</button>`).join('')}${dayMs.map(m=>`<button class="milestone-chip" data-project-open="${m.projectId}" title="Веха">◆ ${esc(m.title)}</button>`).join('')}${dayTasks.slice(0,4).map(t=>`<button class="cal-task status-border-${effectiveStatus(t)}" data-task="${t.id}">${esc(t.title)}</button>`).join('')}${dayTasks.length>4?`<small>+ ещё ${dayTasks.length-4}</small>`:''}</div>`}html+='</div>';el.innerHTML=html;
  el.querySelectorAll('[data-calnav]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.calnav);if(n===0)monthAnchor=new Date();else monthAnchor.setMonth(monthAnchor.getMonth()+n);renderMonth(el,items)});el.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{selectedTaskId=b.dataset.task;selectedProjectId=null;renderInspector()});el.querySelectorAll('[data-project-open]').forEach(b=>b.onclick=()=>{selectedProjectId=b.dataset.projectOpen;selectedTaskId=null;renderInspector()});el.querySelectorAll('[data-event]').forEach(b=>b.onclick=e=>{e.stopPropagation();openEventModal(state.events.find(x=>x.id===b.dataset.event))});if(isAdmin())el.querySelectorAll('[data-day]').forEach(c=>c.ondblclick=()=>openEventModal(null,c.dataset.day))
}
// Calendar events without tasks: meetings, performances, deadlines of partners. Managers add them, everyone sees them.
function openEventModal(ev,date){const edit=isAdmin(),e=ev||{title:'',date:date||todayISO(),endDate:'',time:'',place:'',note:''};
  if(!edit){const b=modal(`<h2>${esc(e.title)}</h2><p>${fmtLong(e.date)}${e.endDate&&e.endDate!==e.date?' — '+fmtLong(e.endDate):''}${e.time?' · '+esc(e.time):''}</p>${e.place?`<p><b>Где:</b> ${esc(e.place)}</p>`:''}${e.note?`<p>${esc(e.note)}</p>`:''}<div class="modal-actions"><button class="btn" data-close>Закрыть</button></div>`);b.querySelector('[data-close]').onclick=()=>b.remove();return}
  const b=modal(`<h2>${ev?'Событие':'Новое событие'}</h2><p class="data-note">Событие видно всей команде в календаре. Задачей оно не становится.</p><div class="field"><label>Название</label><input id="evTitle" maxlength="300" value="${esc(e.title)}" placeholder="Например: репетиция в КЦ «Чулпан»"></div><div class="grid2"><div class="field"><label>Дата</label><input type="date" id="evDate" value="${esc(e.date)}"></div><div class="field"><label>По (если несколько дней)</label><input type="date" id="evEnd" value="${esc(e.endDate)}"></div></div><div class="grid2"><div class="field"><label>Время</label><input type="time" id="evTime" value="${esc(e.time)}"></div><div class="field"><label>Место</label><input id="evPlace" maxlength="300" value="${esc(e.place)}"></div></div><div class="field"><label>Заметка</label><textarea id="evNote" maxlength="3000">${esc(e.note)}</textarea></div><p class="form-error" data-error role="alert"></p><div class="modal-actions">${ev?'<button class="btn ghost" data-delete>Удалить</button>':''}<button class="btn ghost" data-close>Отмена</button><button class="btn primary" data-save>Сохранить</button></div>`);
  b.querySelector('[data-close]').onclick=()=>b.remove();
  b.querySelector('[data-delete]')?.addEventListener('click',()=>{if(!confirm('Удалить событие?'))return;state.events=state.events.filter(x=>x.id!==ev.id);scheduleSave();b.remove();renderMain();toast('Событие удалено')});
  b.querySelector('[data-save]').onclick=()=>{const v=k=>b.querySelector(k).value.trim(),next={title:v('#evTitle'),date:v('#evDate'),endDate:v('#evEnd'),time:v('#evTime'),place:v('#evPlace'),note:v('#evNote')};if(!next.title||!next.date){b.querySelector('[data-error]').textContent='Укажите название и дату';return}if(next.endDate&&next.endDate<next.date){b.querySelector('[data-error]').textContent='Дата окончания раньше даты начала';return}if(next.endDate===next.date)next.endDate='';if(ev)Object.assign(ev,next);else state.events.push({id:id(),...next,createdAt:new Date().toISOString()});scheduleSave();b.remove();if(next.date.slice(0,7)!==iso(monthAnchor).slice(0,7))monthAnchor=new Date(next.date+'T12:00:00');renderMain();toast(ev?'Событие сохранено':'Событие добавлено')};
  setTimeout(()=>b.querySelector('#evTitle').focus(),0)}
function renderTimeline(el,items){
  const days=21,start=new Date(timelineStart);const dates=Array.from({length:days},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return d});
  const projectIds=currentProject==='all'?[...new Set(items.map(t=>t.projectId).filter(Boolean))]:[currentProject].filter(x=>x!=='inbox');
  let html=`<div class="calendar-nav"><button class="btn" data-tlnav="-7">← 7 дней</button><button class="btn ghost" data-tlnav="0">Сегодня</button><button class="btn" data-tlnav="7">7 дней →</button></div><div class="timeline" style="--days:${days}"><div class="timeline-head"><div class="tl-label">Проект / задача</div>${dates.map(d=>`<div class="tl-day ${iso(d)===todayISO()?'tl-today':''}"><b>${d.getDate()}</b><small>${d.toLocaleDateString('ru-RU',{weekday:'short'})}</small></div>`).join('')}</div>`;
  for(const pid of projectIds){const p=projectBy(pid);const pTasks=items.filter(t=>t.projectId===pid);if(!p)continue;html+=`<div class="tl-project"><div class="tl-project-title" data-project-open="${pid}">${esc(p.name)} <span>${projectProgress(pid)}%</span></div></div>`;for(const t of pTasks){const s=t.startDate||t.dueDate,e=t.dueDate||t.startDate;if(!s&&!e)continue;const startIdx=Math.max(0,dayDiff(iso(start),s)),endIdx=Math.min(days-1,dayDiff(iso(start),e));if(endIdx<0||startIdx>=days)continue;const left=startIdx+1,width=Math.max(1,endIdx-startIdx+1);html+=`<div class="tl-row"><button class="tl-label tl-task-label" data-task="${t.id}">${esc(t.title)}</button><div class="tl-track">${dates.map(d=>`<span class="${iso(d)===todayISO()?'tl-today-bg':''}"></span>`).join('')}<button class="tl-bar status-bg-${effectiveStatus(t)}" data-task="${t.id}" style="--start:${left};--span:${width}">${esc(stageBy(t.stageId)?.name||'')}</button></div></div>`}for(const m of projectMilestones(pid)){const idx=dayDiff(iso(start),m.dueDate);if(idx<0||idx>=days)continue;html+=`<div class="tl-row milestone-row"><div class="tl-label">◆ ${esc(m.title)}</div><div class="tl-track">${dates.map(()=>'<span></span>').join('')}<button class="tl-milestone" data-project-open="${pid}" style="--start:${idx+1}">◆</button></div></div>`}}
  html+='</div>';el.innerHTML=html;el.querySelectorAll('[data-tlnav]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.tlnav);timelineStart=n===0?new Date():new Date(timelineStart);if(n===0)timelineStart.setDate(timelineStart.getDate()-3);else timelineStart.setDate(timelineStart.getDate()+n);renderTimeline(el,items)});el.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{selectedTaskId=b.dataset.task;selectedProjectId=null;renderInspector()});el.querySelectorAll('[data-project-open]').forEach(b=>b.onclick=()=>{selectedProjectId=b.dataset.projectOpen;selectedTaskId=null;renderInspector()})
}

let hqSaved=null;
const hqKey=()=>`${currentProject}|${scope}`;
function renderHQ(main){
  main.innerHTML=`<div class="hq-shell"><div class="hq-canvas" id="hqCanvas"></div><div class="hq-toolbar"><span class="hq-title" title="Тяните фон — двигать доску · колесо — масштаб · двойной клик — открыть задачу · клик по нити — выбрать связь">Связи</span><button class="btn active" data-hqmode="select">Выбор</button><button class="btn" data-hqmode="connect">Протянуть нить</button><button class="btn" id="fitHQ">Показать всё</button><button class="btn ${scope==='critical'?'active':''}" id="criticalHQ">Критический путь</button></div><aside class="ib-legend"><h4>Нити</h4>${REL_TYPES.map(([v,n])=>`<div><i class="${v==='related'?'dash':''}" style="--c:${LINKS[v].color}"></i>${esc(n.toLowerCase())}</div>`).join('')}</aside><div class="ib-linkbar" hidden></div><div class="ib-choice" hidden></div></div>`;
  const linkbar=main.querySelector('.ib-linkbar'),choice=main.querySelector('.ib-choice');
  const showLink=l=>{if(!l){linkbar.hidden=true;return}const a=taskBy(l.a),b=taskBy(l.b),label=(REL_TYPES.find(x=>x[0]===l.type)?.[1]||'Связано').toLowerCase();linkbar.innerHTML=`<span class="ib-linkbar-text"><b>${esc(a?.title||'Задача')}</b> <em style="--c:${LINKS[l.type]?.color||LINKS.related.color}">${esc(label)}</em> <b>${esc(b?.title||'Задача')}</b></span>${isAdmin()?'<button class="danger" data-del-link>Удалить связь</button>':''}<button data-close-link aria-label="Закрыть">✕</button>`;linkbar.hidden=false;linkbar.querySelector('[data-close-link]').onclick=()=>{linkbar.hidden=true;hq?.select(null)};const del=linkbar.querySelector('[data-del-link]');if(del)del.onclick=()=>{state.relations=state.relations.filter(r=>l.id?r.id!==l.id:!(r.sourceId===l.a&&r.targetId===l.b&&r.type===l.type));scheduleSave();renderInspector();renderMain();toast('Связь удалена')}};
  const chooseType=(a,b)=>{const ta=taskBy(a),tb=taskBy(b),hint={blocks:'вторая ждёт первую',depends:'первая ждёт вторую',approval:'вторая ждёт решения по первой',related:'без влияния на статус'};choice.innerHTML=`<div class="ib-choice-box" role="dialog" aria-modal="true"><h3>Протянуть нить</h3><p><b>${esc(ta?.title||'Задача')}</b> → <b>${esc(tb?.title||'Задача')}</b></p><div class="opts">${REL_TYPES.map(([v,n])=>`<button data-type="${v}" style="--c:${LINKS[v].color}"><i></i><span>${esc(n)}<small>${hint[v]||''}</small></span></button>`).join('')}</div><button class="cancel" data-cancel>Отмена</button></div>`;choice.hidden=false;choice.onclick=e=>{if(e.target===choice||e.target.closest('[data-cancel]'))choice.hidden=true};choice.querySelectorAll('[data-type]').forEach(x=>x.onclick=()=>{choice.hidden=true;addRelation(a,b,x.dataset.type)})};
  try{
    hq=new HQView(document.querySelector('#hqCanvas'),{onSelect:taskId=>{if(taskId)linkbar.hidden=true;selectedTaskId=taskId;selectedProjectId=null;renderInspector()},onOpen:taskId=>{selectedTaskId=taskId;selectedProjectId=null;renderInspector()},onMove:(taskId,pos)=>{const t=taskBy(taskId);if(t){t.relationsPos=pos;scheduleSave()}},onCreateRelation:chooseType,onLink:showLink,onMode:mode=>main.querySelectorAll('[data-hqmode]').forEach(x=>x.classList.toggle('active',x.dataset.hqmode===mode))});
    renderHQData();
    main.querySelectorAll('[data-hqmode]').forEach(b=>b.onclick=()=>hq.setMode(b.dataset.hqmode==='connect'&&hq.mode==='connect'?'select':b.dataset.hqmode));
    main.querySelector('#fitHQ').onclick=()=>hq.fit();main.querySelector('#criticalHQ').onclick=()=>{scope=scope==='critical'?'all':'critical';renderAll(false)};
    if(hqFocusId){const id=hqFocusId;hqFocusId=null;requestAnimationFrame(()=>hq?.focus(id))}else if(hqSaved&&hqSaved.key===hqKey())hq.restore(hqSaved.view);else requestAnimationFrame(()=>hq?.fit());
  }catch(e){console.warn('Relations board unavailable',e);renderHQFallback(main)}
}
function renderHQFallback(main){const items=filteredTasks(),ids=new Set(items.map(t=>t.id)),rels=state.relations.filter(r=>ids.has(r.sourceId)&&ids.has(r.targetId));main.innerHTML=`<div class="main-scroll relation-fallback"><div class="page-head"><div><div class="eyebrow">Упрощённый режим</div><h1>Связи задач</h1><p>Не удалось открыть доску связей. Все зависимости остаются доступны в списке.</p></div><button class="btn" data-try-3d>Открыть доску снова</button></div><div class="relation-projects">${state.projects.filter(p=>!p.archived&&(currentProject==='all'||p.id===currentProject)).map(p=>`<section class="relation-project"><h2>${esc(p.name)}</h2>${items.filter(t=>t.projectId===p.id).map(t=>`<button data-task="${t.id}" class="relation-task"><b>${esc(t.title)}</b>${taskStatusChip(t)}<small>${esc(t.assignee||'Без ответственного')} · ${fmtDate(t.dueDate)}</small></button>`).join('')||'<div class="home-empty">Нет задач</div>'}</section>`).join('')}</div><section class="relation-list"><h2>Зависимости</h2>${rels.map(r=>`<button data-task="${r.sourceId}"><b>${esc(taskBy(r.sourceId)?.title||'Задача')}</b><span>${esc(REL_TYPES.find(x=>x[0]===r.type)?.[1]||r.type).toLowerCase()} →</span><b>${esc(taskBy(r.targetId)?.title||'Задача')}</b></button>`).join('')||'<div class="home-empty">Связей пока нет</div>'}</section></div>`;main.querySelectorAll('[data-task]').forEach(x=>x.onclick=()=>{selectedTaskId=x.dataset.task;selectedProjectId=null;renderInspector()});main.querySelector('[data-try-3d]').onclick=()=>renderHQ(main)}
function renderHQData(){if(!hq)return;const tasks=filteredTasks().map(t=>({...t,status:effectiveStatus(t)})),ids=new Set(tasks.map(t=>t.id)),projects=currentProject==='all'||currentProject==='inbox'?state.projects:state.projects.filter(p=>p.id===currentProject);hq.setData({projects,tasks,stages:state.stages,relations:state.relations.filter(r=>ids.has(r.sourceId)&&ids.has(r.targetId))});if(selectedTaskId&&ids.has(selectedTaskId))hq.select(selectedTaskId)}

function renderInspector(){const el=document.querySelector('#inspector');if(!el)return;updateUrl();if(selectedTaskId){const task=taskBy(selectedTaskId);if(hosted&&task)return workflow.inspector(el,task,renderTaskInspector);renderTaskInspector(el,task);if(task&&isAdmin())documentsUI.mountLinks(el,task);return;}if(selectedProjectId){renderProjectInspector(el,projectBy(selectedProjectId));if(isAdmin())documentsUI.mountLinks(el,{projectId:selectedProjectId});if(!isAdmin())el.querySelectorAll('input,textarea,select,button:not(#closeInspector)').forEach(c=>c.disabled=true);return;}el.className='inspector empty';el.innerHTML='<div><b>Выберите задачу или проект</b><p>Здесь появятся детали, этапы, вехи и зависимости.</p></div>'}
