function renderTaskInspector(el,t){if(!t){selectedTaskId=null;return renderInspector()}el.className='inspector';const rels=state.relations.filter(r=>r.sourceId===t.id||r.targetId===t.id), blockers=autoBlockers(t),stages=projectStages(t.projectId);el.innerHTML=`<div class="inspector-inner"><div class="inspector-head"><div><div class="eyebrow">${esc(projectBy(t.projectId)?.name||'Входящие')}</div><h2>${esc(t.title)}</h2></div><button class="icon-btn close-inspector" id="closeInspector">×</button></div>${(()=>{const st=effectiveStatus(t),waits=state.tasks.filter(x=>x.id!==t.id&&autoBlockers(x).some(b=>b.id===t.id)),link=x=>`<button class="ins-link" data-goto="${x.id}"><span>${esc(x.title)}</span><small>${esc(x.assignee||'без ответственного')} · ${statusName(effectiveStatus(x)).toLowerCase()}</small></button>`;return`<div class="ins-read"><div class="ins-chips">${taskStatusChip(t)}<span class="priority-chip priority-${t.priority}">${priorityName(t.priority)}</span></div><dl class="ins-facts"><div><dt>Ответственный</dt><dd>${esc(t.assignee||'не назначен')}</dd></div><div><dt>Срок</dt><dd class="${isOverdue(t)?'overdue':''}">${t.dueDate?fmtLong(t.dueDate):'без срока'}${isOverdue(t)?' · просрочено':''}</dd></div><div><dt>Этап</dt><dd>${esc(stageBy(t.stageId)?.name||'—')}</dd></div><div><dt>Готовность</dt><dd><span class="ins-progress"><i style="width:${t.progress||0}%"></i></span>${t.progress||0}%</dd></div></dl>${t.description?`<p class="ins-desc">${esc(t.description)}</p>`:''}${blockers.length?`<div class="ins-waits is-blocked"><b>Ждёт — сначала нужно завершить</b>${blockers.map(link).join('')}</div>`:''}${waits.length?`<div class="ins-waits"><b>От неё зависят</b>${waits.map(link).join('')}</div>`:''}<div class="ins-quick">${st!=='done'&&!blockers.length&&canEditTask(t)?'<button class="btn primary" data-quick-done>Готово</button>':''}${rels.length?'<button class="btn" data-quick-chain>Показать цепочку</button>':''}</div></div>`})()}<details class="ins-edit" ${inspectorEditOpen?'open':''}><summary>Изменить задачу</summary><div class="field"><label>Название</label><input id="iTitle" value="${esc(t.title)}"></div><div class="field"><label>Описание</label><textarea id="iDesc">${esc(t.description||'')}</textarea></div><div class="grid2"><div class="field"><label>Статус</label><select id="iStatus">${STATUS.map(([v,n])=>`<option value="${v}" ${t.status===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>Приоритет</label><select id="iPriority">${PRIORITY.map(([v,n])=>`<option value="${v}" ${t.priority===v?'selected':''}>${n}</option>`).join('')}</select></div></div><div class="grid2"><div class="field"><label>Начало</label><input type="date" id="iStart" value="${esc(t.startDate||'')}"></div><div class="field"><label>Срок</label><input type="date" id="iDue" value="${esc(t.dueDate||'')}"></div></div><div class="field"><label>Ответственный</label><input id="iAssignee" value="${esc(t.assignee||'')}"></div><div class="field"><label>Проект</label><select id="iProject"><option value="">Входящие</option>${state.projects.map(p=>`<option value="${p.id}" ${t.projectId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>Этап</label><select id="iStage"><option value="">Без этапа</option>${stages.map(s=>`<option value="${s.id}" ${t.stageId===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Прогресс · ${t.progress||0}%</label><input type="range" min="0" max="100" step="5" id="iProgress" value="${t.progress||0}"></div></details><div class="ins-section"><h3>Чек-лист</h3>${(t.checklist||[]).map((c,i)=>`<label class="check-row"><input type="checkbox" data-check="${i}" ${c.done?'checked':''}><span>${esc(c.text)}</span></label>`).join('')||'<div class="task-sub">Пока пусто</div>'}<div class="add-check"><input id="newCheck" placeholder="Добавить пункт"><button class="btn" id="addCheck">+</button></div></div><div class="ins-section"><h3>Зависимости</h3>${rels.map(r=>{const other=taskBy(r.sourceId===t.id?r.targetId:r.sourceId);return`<div class="relation"><div>${esc(other?.title||'Удалённая задача')}<br><small>${REL_TYPES.find(x=>x[0]===r.type)?.[1]||r.type}</small></div><button class="icon-btn" data-delrel="${r.id}">×</button></div>`}).join('')||'<div class="task-sub">Связей пока нет</div>'}<button class="btn" id="addRelationBtn" style="margin-top:8px">+ Добавить зависимость</button></div><div class="ins-section"><button class="danger-btn" id="deleteTask">Удалить задачу</button></div></div>`;
  const bind=(q,key,evt='change',map=v=>v)=>el.querySelector(q)?.addEventListener(evt,e=>updateTask(t.id,{[key]:map(e.target.value)}));bind('#iTitle','title','change');bind('#iDesc','description','change');bind('#iStatus','status');bind('#iPriority','priority');bind('#iStart','startDate');bind('#iDue','dueDate');bind('#iAssignee','assignee','change');el.querySelector('#iProject').onchange=e=>{const pid=e.target.value;updateTask(t.id,{projectId:pid,stageId:projectStages(pid)[0]?.id||''})};bind('#iStage','stageId');bind('#iProgress','progress','input',Number);el.querySelectorAll('[data-check]').forEach(x=>x.onchange=()=>{t.checklist[Number(x.dataset.check)].done=x.checked;scheduleSave()});el.querySelector('#addCheck').onclick=()=>{const inp=el.querySelector('#newCheck');if(!inp.value.trim())return;t.checklist.push({text:inp.value.trim(),done:false});scheduleSave();renderInspector()};el.querySelectorAll('[data-delrel]').forEach(x=>x.onclick=()=>{state.relations=state.relations.filter(r=>r.id!==x.dataset.delrel);scheduleSave();renderInspector();renderMain()});el.querySelector('#addRelationBtn').onclick=()=>openRelationModal(t.id);el.querySelector('#deleteTask').onclick=()=>deleteTask(t.id);const help=document.createElement('button');help.className='btn';help.textContent='Сообщить о проблеме';help.onclick=()=>teamUI.openProblem(t.id);el.querySelector('.inspector-inner').append(help);if(!isAdmin()){el.querySelectorAll('input,textarea,select,button').forEach(c=>{if(c===help||c.id==='closeInspector'||c.closest('.ins-read'))return;if((c.id==='iStatus'||c.id==='iProgress'||c.hasAttribute('data-check'))&&canEditTask(t))return;c.disabled=true});el.querySelector('#deleteTask').hidden=true;el.querySelector('#addRelationBtn').hidden=true;}el.querySelector('#closeInspector')?.addEventListener('click',()=>{selectedTaskId=null;renderInspector()});el.querySelector('.ins-edit').ontoggle=e=>{inspectorEditOpen=e.target.open};el.querySelectorAll('[data-goto]').forEach(x=>x.onclick=()=>{selectedTaskId=x.dataset.goto;renderInspector()});el.querySelector('[data-quick-done]')?.addEventListener('click',()=>runAction('done',t.id));el.querySelector('[data-quick-chain]')?.addEventListener('click',()=>showChain(t.id))
}
function renderProjectInspector(el,p){if(!p){selectedProjectId=null;return renderInspector()}el.className='inspector';const stages=projectStages(p.id),ms=projectMilestones(p.id),tasks=projectTasks(p.id),critical=criticalPath(p.id).map(taskBy).filter(Boolean);el.innerHTML=`<div class="inspector-inner"><div class="inspector-head"><div><div class="eyebrow">Проект</div><h2>${esc(p.name)}</h2></div><button class="icon-btn close-inspector" id="closeInspector" aria-label="Закрыть">×</button></div><div class="project-health"><div><strong>${projectSchedule(p.id).progress.percent}%</strong><span>${projectSchedule(p.id).progress.doneDays} из ${projectSchedule(p.id).progress.totalDays} ${word(projectSchedule(p.id).progress.totalDays,'дня','дней','дней')} работы</span></div><div><strong>${tasks.length}</strong><span>${word(tasks.length,'задача','задачи','задач')}</span></div><div><strong>${projectRiskCount(p.id)}</strong><span>${word(projectRiskCount(p.id),'риск','риска','рисков')}</span></div></div><div class="field"><label>Название</label><input id="pName" value="${esc(p.name)}"></div><div class="field"><label>Цель и результат</label><textarea id="pDesc">${esc(p.description||'')}</textarea></div><div class="field"><label>Руководитель</label><input id="pOwner" value="${esc(p.owner||'')}"></div><div class="field"><label>Участники через запятую</label><input id="pMembers" value="${esc((p.members||[]).join(', '))}"></div><div class="grid2"><div class="field"><label>Начало</label><input type="date" id="pStart" value="${esc(p.startDate||'')}"></div><div class="field"><label>Дедлайн</label><input type="date" id="pDue" value="${esc(p.dueDate||'')}"></div></div><div class="ins-section"><div class="section-head"><h3>Этапы</h3><button class="btn mini" id="addStage">+ Этап</button></div>${stages.map((s,i)=>`<div class="stage-row"><span><b>${i+1}</b>${esc(s.name)}</span><small>${tasks.filter(t=>t.stageId===s.id).length} ${word(tasks.filter(t=>t.stageId===s.id).length,'задача','задачи','задач')}</small></div>`).join('')||'<div class="task-sub">Нет этапов</div>'}</div><div class="ins-section"><div class="section-head"><h3>Вехи</h3><button class="btn mini" id="addMilestone">+ Веха</button></div>${ms.map(m=>`<label class="milestone-row-ins"><input type="checkbox" data-msdone="${m.id}" ${m.done?'checked':''}><span><b>${esc(m.title)}</b><small>${fmtLong(m.dueDate)}</small></span><button class="icon-btn" aria-label="Удалить веху" data-delms="${m.id}">×</button></label>`).join('')||'<div class="task-sub">Нет вех</div>'}</div><div class="ins-section"><h3>Критический путь</h3>${critical.length?`<div class="critical-chain">${critical.map((t,i)=>`<button data-task="${t.id}">${i+1}. ${esc(t.title)}</button>`).join('<span>→</span>')}</div>`:'<div class="task-sub">Недостаточно зависимостей для расчёта</div>'}</div><div class="ins-section project-actions"><button class="btn" id="duplicateProject">Создать копию</button><button class="btn" id="archiveProject">${p.archived?'Вернуть из архива':'Архивировать'}</button><button class="danger-btn" id="deleteProject">Удалить проект</button></div></div>`;
  const upd=(key,val)=>{const next={...p,[key]:val};if(next.startDate&&next.dueDate&&next.dueDate<next.startDate){toast('Дедлайн не может быть раньше даты начала');renderInspector();return}p[key]=val;p.updatedAt=new Date().toISOString();scheduleSave();renderSidebar();renderMain()};['Name','Desc','Owner','Start','Due'].forEach(s=>el.querySelector(`#p${s}`)?.addEventListener('change',e=>upd({Name:'name',Desc:'description',Owner:'owner',Start:'startDate',Due:'dueDate'}[s],e.target.value)));el.querySelector('#pMembers').onchange=e=>upd('members',e.target.value.split(',').map(x=>x.trim()).filter(Boolean));el.querySelector('#addStage').onclick=()=>openStageModal(p.id);el.querySelector('#addMilestone').onclick=()=>openMilestoneModal(p.id);el.querySelectorAll('[data-msdone]').forEach(x=>x.onchange=()=>{const m=state.milestones.find(m=>m.id===x.dataset.msdone);if(m)m.done=x.checked;scheduleSave()});el.querySelectorAll('[data-delms]').forEach(x=>x.onclick=e=>{e.preventDefault();state.milestones=state.milestones.filter(m=>m.id!==x.dataset.delms);scheduleSave();renderProjectInspector(el,p);renderMain()});el.querySelectorAll('[data-task]').forEach(x=>x.onclick=()=>{selectedTaskId=x.dataset.task;selectedProjectId=null;renderInspector();hq?.focus?.(x.dataset.task)});el.querySelector('#duplicateProject').onclick=()=>duplicateProject(p.id);el.querySelector('#archiveProject').onclick=()=>{p.archived=!p.archived;if(p.archived&&currentProject===p.id)currentProject='all';selectedProjectId=null;scheduleSave();renderAll(false);toast(p.archived?'Проект перемещён в архив':'Проект возвращён')};el.querySelector('#deleteProject').onclick=()=>deleteProject(p.id);el.querySelector('#closeInspector')?.addEventListener('click',()=>{selectedProjectId=null;renderInspector()})
}

function closeModal(b){if(b.dataset.changed==='true'&&!confirm('Закрыть окно без сохранения введённых данных?'))return;b.remove();}
function modal(content){document.querySelector('.modal-backdrop')?.remove();const b=document.createElement('div');b.className='modal-backdrop';b.innerHTML=`<div class="modal" role="dialog" aria-modal="true">${content}</div>`;document.body.appendChild(b);b.onclick=e=>{if(e.target===b)closeModal(b)};b.addEventListener('input',()=>{b.dataset.changed='true'});b.addEventListener('change',()=>{b.dataset.changed='true'});b.addEventListener('click',e=>{if(e.target.closest('[data-close]')&&b.dataset.changed==='true'&&!confirm('Закрыть окно без сохранения введённых данных?')){e.preventDefault();e.stopImmediatePropagation()}},true);b.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const items=[...b.querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled&&x.getClientRects().length);if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});queueMicrotask(()=>b.querySelector('input:not([disabled]),textarea,select,button')?.focus());b.querySelectorAll('.field').forEach((f,i)=>{const label=f.querySelector('label'),control=f.querySelector('input,textarea,select');if(label&&control){control.id||=`modalField${i}`;label.htmlFor=control.id}});return b}
function openQuickModal(){openTaskModal();}
function openTaskModal(){
  const defaultProject=state.projects.some(p=>p.id===currentProject&&!p.archived)?currentProject:'';
  const names=hosted?session.team.filter(m=>m.active||m.pending).map(m=>m.name):[...new Set(state.tasks.flatMap(t=>String(t.assignee||'').split(',').map(x=>x.trim())).filter(Boolean))];
  const b=modal(`<h2>Новая задача</h2><p>Достаточно названия. Остальное можно добавить позже.</p><form data-task-form><div class="field"><label>Что должно быть сделано</label><input id="mTitle" required maxlength="300" placeholder="Например: согласовать программу форума"></div><div class="grid2"><div class="field"><label>Кто отвечает</label>${hosted?`<select id="mAssignee" ${!isAdmin()?'disabled':''}><option value="">Не назначен</option>${names.map(n=>`<option ${!isAdmin()&&n===session.me.name?'selected':''}>${esc(n)}</option>`).join('')}</select>`:`<input id="mAssignee" list="taskPeople"><datalist id="taskPeople">${names.map(n=>`<option value="${esc(n)}">`).join('')}</datalist>`}</div><div class="field"><label>К какому сроку</label><input id="mDue" type="date"></div></div><details class="task-options"><summary>${defaultProject?esc(projectBy(defaultProject)?.name)+' · подробности':'Проект и подробности'}</summary><div class="field"><label>Проект</label><select id="mProject"><option value="">Без проекта · Входящие</option>${state.projects.filter(p=>!p.archived).map(p=>`<option value="${p.id}" ${p.id===defaultProject?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div>${isAdmin()?`<div class="field"><label>Описание</label><textarea id="mDescription" maxlength="5000" placeholder="Подробности, которые помогут выполнить задачу"></textarea></div><div class="field"><label>Ожидаемый результат</label><textarea id="mResult" maxlength="5000" placeholder="Что нужно передать: файл, ссылка, согласованная программа…"></textarea></div>${hosted?'<label class="check-row"><input type="checkbox" id="mReview"> Нужна проверка руководителя</label><p class="review-explanation" data-review-explanation>Без проверки: достаточно отметить задачу выполненной. Файлы и отчёт не нужны.</p>':''}<div class="field"><label>Что проверить / шаги — каждый пункт с новой строки</label><textarea id="mChecklist"></textarea></div>`:''}</details><div class="modal-actions"><button type="button" class="btn ghost" data-close>Отмена</button><button class="btn primary" type="submit">Создать задачу</button></div></form>`);
  b.querySelector('#mReview')?.addEventListener('change',e=>{b.querySelector('[data-review-explanation]').textContent=e.target.checked?'С проверкой: исполнитель сдаст результат комментарием, ссылкой или файлом.':'Без проверки: достаточно отметить задачу выполненной. Файлы и отчёт не нужны.';});
  b.querySelector('form').onsubmit=e=>{e.preventDefault();const title=b.querySelector('#mTitle').value.trim();if(!title){b.querySelector('#mTitle').focus();return;}addTask({title,projectId:b.querySelector('#mProject').value,dueDate:b.querySelector('#mDue').value,assignee:hosted&&!isAdmin()?session.me.name:b.querySelector('#mAssignee').value,description:b.querySelector('#mDescription')?.value.trim()||'',expectedResult:b.querySelector('#mResult')?.value.trim()||'',requiresReview:!!b.querySelector('#mReview')?.checked,checklist:(b.querySelector('#mChecklist')?.value||'').split('\n').map(x=>x.trim()).filter(Boolean).map(text=>({text,done:false}))},{quick:true});b.remove();};
  b.querySelector('[data-close]').onclick=()=>b.remove();setTimeout(()=>b.querySelector('#mTitle').focus(),0);
}
function openOrgModal(){if(!isAdmin()){toast('Действие доступно администратору');return;}const b=modal(`<h2>Пространства</h2><p class="data-note">Переименуйте рабочие области или добавьте новую. Пространство с проектами удалить нельзя.</p><div class="org-editor">${state.organizations.map(o=>`<div class="org-edit-row"><span class="dot" style="background:${o.color||COLORS[0]}"></span><input aria-label="Название пространства" data-org-name="${o.id}" value="${esc(o.name)}"><button class="icon-btn" aria-label="Удалить пространство" data-org-delete="${o.id}">×</button></div>`).join('')}</div><div class="field"><label>Новое пространство</label><input id="oName" placeholder="Название"></div><div class="form-error" data-error role="alert"></div><div class="modal-actions"><button class="btn ghost" data-close>Отмена</button><button class="btn primary" id="oSave">Сохранить</button></div>`);b.querySelectorAll('[data-org-delete]').forEach(btn=>btn.onclick=()=>{const oid=btn.dataset.orgDelete;if(state.projects.some(p=>p.orgId===oid)){b.querySelector('[data-error]').textContent='Сначала перенесите или удалите проекты из этого пространства.';return}if(state.organizations.length===1){b.querySelector('[data-error]').textContent='Нужно оставить хотя бы одно пространство.';return}if(!confirm('Удалить пустое пространство?'))return;state.organizations=state.organizations.filter(o=>o.id!==oid);scheduleSave();b.remove();renderAll(true);openOrgModal()});b.querySelector('#oSave').onclick=()=>{b.querySelectorAll('[data-org-name]').forEach(inp=>{const org=state.organizations.find(o=>o.id===inp.dataset.orgName),name=inp.value.trim();if(org&&name)org.name=name});const name=b.querySelector('#oName').value.trim();if(name)state.organizations.push({id:id(),name,color:COLORS[state.organizations.length%COLORS.length]});scheduleSave();b.remove();renderAll(true);toast('Пространства сохранены')};b.querySelector('[data-close]').onclick=()=>b.remove()}
function openProjectModal(){if(!isAdmin()){toast('Действие доступно администратору');return;}
  const b=modal(`<div class="wizard-head"><div><div class="eyebrow">Новый проект</div><h2>Соберите рабочую основу</h2></div><div class="wizard-progress"><i class="active">1</i><i>2</i><i>3</i></div></div><section class="wizard-step active" data-step="1"><div class="field"><label>Название проекта</label><input id="prName" autofocus placeholder="Например: Молодёжный форум"></div><div class="field"><label>Цель и ожидаемый результат</label><textarea id="prDesc" placeholder="Что должно измениться или быть готово"></textarea></div><div class="field"><label>Пространство</label><select id="prOrg">${state.organizations.map(o=>`<option value="${o.id}">${esc(o.name)}</option>`).join('')}</select></div><div class="grid2"><div class="field"><label>Начало</label><input type="date" id="prStart"></div><div class="field"><label>Дедлайн</label><input type="date" id="prDue"></div></div></section><section class="wizard-step" data-step="2"><div class="field"><label>Руководитель</label><input id="prOwner" placeholder="Имя"></div><div class="field"><label>Участники через запятую</label><input id="prMembers" placeholder="Алия, Мария, Алексей"></div><div class="field"><label>Этапы — каждый с новой строки</label><textarea id="prStages">Подготовка\nРеализация\nЗавершение</textarea></div></section><section class="wizard-step" data-step="3"><div class="field"><label>Первые задачи — каждая с новой строки</label><textarea id="prTasks" placeholder="Утвердить концепцию\nСобрать команду"></textarea></div><div class="field"><label>Первая контрольная точка</label><input id="prMilestone" placeholder="Например: Концепция утверждена"></div><div class="field"><label>Дата контрольной точки</label><input type="date" id="prMilestoneDue"></div><div class="wizard-review">После создания все поля можно изменить в карточке проекта.</div></section><div class="form-error" data-error role="alert"></div><div class="modal-actions wizard-actions"><button class="btn ghost" data-close>Отмена</button><button class="btn" data-prev hidden>Назад</button><button class="btn primary" data-next>Далее</button><button class="btn primary" data-create hidden>Создать проект</button></div>`);
  let step=1;const show=()=>{b.querySelectorAll('[data-step]').forEach(x=>x.classList.toggle('active',Number(x.dataset.step)===step));b.querySelectorAll('.wizard-progress i').forEach((x,i)=>x.classList.toggle('active',i<step));b.querySelector('[data-prev]').hidden=step===1;b.querySelector('[data-next]').hidden=step===3;b.querySelector('[data-create]').hidden=step!==3;b.querySelector('[data-error]').textContent=''};const validFirst=()=>{const name=b.querySelector('#prName').value.trim(),start=b.querySelector('#prStart').value,due=b.querySelector('#prDue').value;if(!name)return'Укажите название проекта';if(start&&due&&due<start)return'Дедлайн не может быть раньше даты начала';return''};b.querySelector('[data-next]').onclick=()=>{const error=step===1?validFirst():'';if(error){b.querySelector('[data-error]').textContent=error;return}step=Math.min(3,step+1);show()};b.querySelector('[data-prev]').onclick=()=>{step=Math.max(1,step-1);show()};b.querySelector('[data-close]').onclick=()=>b.remove();b.querySelector('[data-create]').onclick=()=>{const error=validFirst();if(error){step=1;show();b.querySelector('[data-error]').textContent=error;return}const pid=id(),stageNames=b.querySelector('#prStages').value.split(/\n+/).map(x=>x.trim()).filter(Boolean),names=stageNames.length?stageNames:['Подготовка','Реализация','Завершение'],stages=names.map((name,i)=>({id:id(),projectId:pid,name,order:i+1})),owner=b.querySelector('#prOwner').value.trim(),members=b.querySelector('#prMembers').value.split(',').map(x=>x.trim()).filter(Boolean);state.projects.push({id:pid,orgId:b.querySelector('#prOrg').value,name:b.querySelector('#prName').value.trim(),status:'active',archived:false,color:COLORS[state.projects.length%COLORS.length],description:b.querySelector('#prDesc').value.trim(),owner,members,startDate:b.querySelector('#prStart').value,dueDate:b.querySelector('#prDue').value});state.stages.push(...stages);const taskNames=b.querySelector('#prTasks').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);taskNames.forEach(title=>state.tasks.push({id:id(),title,description:'',projectId:pid,stageId:stages[0]?.id||'',status:'planned',priority:'medium',startDate:'',dueDate:'',assignee:owner,progress:0,checklist:[],position:null,inbox:false,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()}));const milestone=b.querySelector('#prMilestone').value.trim();if(milestone)state.milestones.push({id:id(),projectId:pid,stageId:stages[0]?.id||'',title:milestone,dueDate:b.querySelector('#prMilestoneDue').value,done:false});state.meta.demo=false;currentProject=pid;scope='all';selectedProjectId=pid;selectedTaskId=null;scheduleSave();b.remove();renderAll(true);toast('Проект создан')};setTimeout(()=>b.querySelector('#prName').focus(),0)
}
function blankWorkspace(){const org=id();return normalizeState({version:5,meta:{demo:false,createdAt:new Date().toISOString()},organizations:[{id:org,name:'Рабочие проекты',color:COLORS[0]}],projects:[],stages:[],milestones:[],tasks:[],relations:[]})}
function startClean(){if(!isAdmin()){toast('Действие доступно администратору');return;}if(!confirm('Удалить демонстрационные проекты и начать с чистого листа?'))return;state=blankWorkspace();currentProject='all';scope='all';search='';selectedTaskId=null;selectedProjectId=null;scheduleSave();renderAll(true);openProjectModal()}
function exportWorkspace(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`living-project-hq-${todayISO()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Резервная копия сохранена')}
function openDataModal(){const archived=state.projects.filter(p=>p.archived);const b=modal(`<h2>Данные и резервная копия</h2><p class="data-note">${hosted?'Проекты хранятся в общей базе команды. Импорт заменит все общие проекты и задачи. Сначала скачайте копию.':'Проекты хранятся на этом устройстве. Для переноса в командную версию скачайте копию и загрузите её там от имени руководителя.'}</p><div class="data-actions"><button class="btn primary" data-export>Скачать копию</button><label class="btn file-btn">Загрузить копию<input type="file" accept="application/json,.json" data-import></label></div>${archived.length?`<div class="ins-section"><h3>Архив</h3>${archived.map(p=>`<button class="archive-row" data-restore="${p.id}">${esc(p.name)}<span>Восстановить</span></button>`).join('')}</div>`:''}<div class="modal-actions"><button class="btn ghost" data-close>Закрыть</button></div>`);b.querySelector('[data-export]').onclick=exportWorkspace;b.querySelector('[data-import]').onchange=e=>{const file=e.target.files?.[0];if(!file)return;const reader=new FileReader;reader.onload=()=>{try{const incoming=JSON.parse(reader.result);if(!incoming||!Array.isArray(incoming.projects)||!Array.isArray(incoming.tasks))throw new Error;if(!isAdmin()){toast('Импорт доступен администратору');return;}if(!confirm('Заменить все проекты и задачи содержимым копии?'))return;state=normalizeState(incoming);currentProject='all';scope='all';search='';selectedTaskId=null;selectedProjectId=null;scheduleSave();b.remove();renderAll(true);toast('Резервная копия загружена')}catch{b.querySelector('.data-note').textContent='Файл не похож на резервную копию Living Project HQ.'}};reader.readAsText(file)};b.querySelectorAll('[data-restore]').forEach(x=>x.onclick=()=>{const p=projectBy(x.dataset.restore);if(p)p.archived=false;scheduleSave();b.remove();renderAll(true);toast('Проект восстановлен')});b.querySelector('[data-close]').onclick=()=>b.remove()}
function openMobileMenu(){
  const entries=[...(isAdmin()?[['project','+ Новый проект']]:[]),...(hosted&&isAdmin()?[['mine','Мои задачи']]:[]),['problems','Помощь и вопросы'],...(hosted?[['notifications','Уведомления'],['refresh','Обновить данные']]:[]),...(isAdmin()?[['data','Данные и резервная копия'],...(hosted?[['archive','Архив задач']]:[])]:[]),['integrations','Подключения'],...(hosted?[['account','Аккаунт и пароль']]:[]),['all','Все проекты']];
  const b=modal(`<h2>Меню</h2><div class="mobile-action-list">${entries.map(([key,label])=>`<button class="btn" data-menu-action="${key}">${label}</button>`).join('')}</div><div class="modal-actions"><button class="btn ghost" data-close>Закрыть</button></div>`);
  b.querySelectorAll('[data-menu-action]').forEach(btn=>btn.onclick=()=>{const key=btn.dataset.menuAction;b.remove();if(key==='project')openProjectModal();else if(key==='data')openDataModal();else if(key==='account')openAccount(modal,toast);else if(key==='refresh'){if(!dirty&&!isPending())location.reload();else toast('Дождитесь сохранения изменений');}else if(key==='all'){currentProject='all';scope='all';setView('list');}else setView(key);});b.querySelector('[data-close]').onclick=()=>b.remove();
}
function openStageModal(projectId){const b=modal(`<h2>Новый этап</h2><div class="field"><label>Название</label><input id="sName" autofocus placeholder="Например: Закупки"></div><div class="modal-actions"><button class="btn ghost" data-close>Отмена</button><button class="btn primary" id="sSave">Добавить</button></div>`);b.querySelector('#sSave').onclick=()=>{const name=b.querySelector('#sName').value.trim();if(!name)return;state.stages.push({id:id(),projectId,name,order:projectStages(projectId).length+1});scheduleSave();b.remove();renderInspector();renderMain()};b.querySelector('[data-close]').onclick=()=>b.remove()}
function openMilestoneModal(projectId){const stages=projectStages(projectId);const b=modal(`<h2>Новая веха</h2><div class="field"><label>Название</label><input id="msTitle" autofocus placeholder="Например: Программа утверждена"></div><div class="grid2"><div class="field"><label>Дата</label><input type="date" id="msDue"></div><div class="field"><label>Этап</label><select id="msStage"><option value="">Без этапа</option>${stages.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div></div><div class="modal-actions"><button class="btn ghost" data-close>Отмена</button><button class="btn primary" id="msSave">Добавить</button></div>`);b.querySelector('#msSave').onclick=()=>{const title=b.querySelector('#msTitle').value.trim();if(!title)return;state.milestones.push({id:id(),projectId,stageId:b.querySelector('#msStage').value,title,dueDate:b.querySelector('#msDue').value,done:false});scheduleSave();b.remove();renderInspector();renderMain()};b.querySelector('[data-close]').onclick=()=>b.remove()}
function openRelationModal(sourceId){if(!isAdmin()){toast('Действие доступно администратору');return;}const options=state.tasks.filter(t=>t.id!==sourceId).map(t=>`<option value="${t.id}">${esc(t.title)} — ${esc(projectBy(t.projectId)?.name||'Входящие')}</option>`).join('');const b=modal(`<h2>Добавить зависимость</h2><div class="field"><label>Связать с задачей</label><select id="rTask">${options}</select></div><div class="field"><label>Тип</label><select id="rType">${REL_TYPES.map(([v,n])=>`<option value="${v}">${n}</option>`).join('')}</select></div><div class="modal-actions"><button class="btn ghost" data-close>Отмена</button><button class="btn primary" id="rSave">Связать</button></div>`);b.querySelector('#rSave').onclick=()=>{addRelation(sourceId,b.querySelector('#rTask').value,b.querySelector('#rType').value);b.remove()};b.querySelector('[data-close]').onclick=()=>b.remove()}

function renderAll(rebuild=true){if(rebuild)shell();document.querySelectorAll('.view-tabs [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelector('[data-place=work]')?.classList.toggle('active',isWorkView(view));renderSidebar();renderMain();renderInspector();updateUrl()}
addEventListener('keydown',e=>{if(e.key==='Escape'){const m=document.querySelector('.modal-backdrop');if(m){closeModal(m);return}if((selectedTaskId||selectedProjectId)&&view!=='board'&&!e.target.closest?.('input,textarea,select')){selectedTaskId=null;selectedProjectId=null;renderInspector();return}}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();openQuickModal()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('#search')?.focus()}});
addEventListener('living-hq:board-closed',()=>{if(view==='board')setView(lastWorkView)});
addEventListener('beforeunload',e=>{if(dirty||isPending()||documentsUI.isPending()){e.preventDefault();e.returnValue=''}});
addEventListener('unhandledrejection',e=>{if(e.reason?.message){toast(e.reason.message);setSaveState('Ошибка сохранения')}});
scope=SCOPES.some(([k])=>k===initialHash.get('scope'))?initialHash.get('scope'):'all';search=initialHash.get('q')||'';
if(initialHash.get('project')==='inbox')currentProject='inbox';
if(view==='docs'&&!isAdmin())view='home';
renderAll(true);

addEventListener('living-hq:member-task',e=>{setTimeout(()=>{setView('home');if(e.detail.id){selectedTaskId=e.detail.id;selectedProjectId=null;renderInspector()}else openTaskModal()},0)});
